import{z as i,x as s,o as B,c as D,q as t,j as n,D as A,d as e,s as l,S as o,b as a}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"跟踪误差的分解","description":"","frontmatter":{"title":"跟踪误差的分解","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/etf-tracking-error.md","filePath":"quant/etf-tracking-error.md","lastUpdated":1791063341000}'),d={name:"quant/etf-tracking-error.md"};function T(p,E,C,F,m,f){const r=s("Mermaid");return B(),D("div",null,[E[2]||(E[2]=t('<h1 id="跟踪误差的分解" tabindex="-1">跟踪误差的分解 <a class="header-anchor" href="#跟踪误差的分解" aria-label="Permalink to &quot;跟踪误差的分解&quot;">​</a></h1><div class="epigraph"><p>跟踪差异是账，跟踪误差是波；只报波动率的验收书，藏得住一笔每年确定发生的亏欠。</p><footer>—— 口径据 Roll, Journal of Portfolio Management, 1992 与发行人年报的「跟踪差异 vs 跟踪误差」披露整理</footer></div><p><a href="/quant/etf-create-redeem-arb">上一课</a>写清了申赎管道如何把二级价格钉在可复制篮子附近；它钉住的是价格对篮子，没有钉住净值对指数。缺口就在这里：即便折溢价为零，基金净值仍可以稳定地落后于指数。本课把「净值减指数」拆成有名字的项，给出每一项的修正动作。TE 约束下的主动组合见<a href="/quant/benchmark-tracking-error">基准与跟踪误差</a>，本课只写被动产品的误差谱系。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>先分清两个量。跟踪差异 TD 是 \\(\\sum_t (r_{f,t} - r_{I,t})\\)，有符号，回答「落在指数后面多少」；跟踪误差 TE 是 \\(r_f - r_I\\) 的标准差，无符号，回答「贴得稳不稳」。费率是每天 \\(-\\phi/252\\) 的确定性项，全部进了 TD、几乎不进 TE；只验收 TE 的合同，允许管理人用「波动很小但系统性落后」的产品过关。反过来只看 TD，会把一次事件冲击的运气当成能力。两个量回答两个问题，验收必须都要。</p><p><span class="marginnote">跨境与债券 ETF 的日频 TE 会被陈旧价格压低：底层闭市时，基金净值停在昨日，指数仍按模型或矩阵定价走动，日收益差的波动被系统性低估。比较产品要用同时区重估或更长周期，日频 TE 排行榜不可直接比。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把每日差 \\(d_t = r_{f,t} - r_{I,t}\\) 按来源记账：</p><p><span class="marginnote">把数字代进去感受一下：费率 0.50% 的产品每天确定性落后 \\(0.50\\%/252\\approx0.002\\%\\)，一年恰好累计 0.50%，全部记进 TD；而只要每日差波动不大，TE 可以只有个位数基点。这就是「只验 TE」的合同漏洞——落后的钱是确定的，报表上的波动却几乎为零。</span></p> \\[d_t \\approx -\\phi/252 + \\delta_{\\mathrm{cash},t} + \\epsilon_{\\mathrm{samp},t} - c_{\\mathrm{trade},t} + \\ell_t + \\eta_t \\]<p>五项各有定义与修法。费用项由费率决定，修正动作是选产品。现金拖累 \\(\\delta\\) 来自分红在途、申赎现金在途与未投资头寸——现金在牛市里就是负alpha，修正动作是管申赎节奏与股票化，<a href="/quant/index-rebalance">指数调入调出</a>一课的口径同样适用。抽样残差 \\(\\epsilon\\) 是优化复制的代价：成分多、流动性差的指数不做全复制，残差要用事前协方差预算。交易成本 \\(c\\) 集中在再平衡、换样与公司行动日，是可以预告的事件。借出收入 \\(\\ell\\) 是唯一的正项：宽基 ETF 把篮子借给空头，收入可以覆盖费率，这是许多产品 TD 接近零甚至为正的机制。</p>',11)),(B(),n(o,null,{default:A(()=>[l(r,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20DIF%5B%22%E5%87%80%E5%80%BC%E5%87%8F%E6%8C%87%E6%95%B0%20d_t%22%5D%20--%3E%20FEE%5B%22%E8%B4%B9%E7%94%A8%EF%BC%9A-%E8%B4%B9%E7%8E%87%2F252%22%5D%0A%20%20DIF%20--%3E%20CASH%5B%22%E7%8E%B0%E9%87%91%E6%8B%96%E7%B4%AF%EF%BC%9A%E5%88%86%E7%BA%A2%E4%B8%8E%E7%94%B3%E8%B5%8E%E5%9C%A8%E9%80%94%22%5D%0A%20%20DIF%20--%3E%20SAMP%5B%22%E6%8A%BD%E6%A0%B7%E6%AE%8B%E5%B7%AE%EF%BC%9A%E4%BC%98%E5%8C%96%E5%A4%8D%E5%88%B6%22%5D%0A%20%20DIF%20--%3E%20TRD%5B%22%E4%BA%8B%E4%BB%B6%E6%88%90%E6%9C%AC%EF%BC%9A%E5%86%8D%E5%B9%B3%E8%A1%A1%E4%B8%8E%E5%85%AC%E5%8F%B8%E8%A1%8C%E5%8A%A8%22%5D%0A%20%20DIF%20--%3E%20LEND%5B%22%E5%80%9F%E5%87%BA%E6%94%B6%E5%85%A5%EF%BC%9A%E5%94%AF%E4%B8%80%E6%AD%A3%E9%A1%B9%22%5D%0A%20%20DIF%20--%3E%20NOISE%5B%22%E4%BC%B0%E5%80%BC%E5%99%AA%E5%A3%B0%EF%BC%9A%E6%97%B6%E5%B7%AE%E4%B8%8E%E5%81%9C%E7%89%8C%22%5D%0A%20%20FEE%20--%3E%20ACT%5B%22%E9%80%89%E4%BA%A7%E5%93%81%22%5D%0A%20%20CASH%20--%3E%20ACT2%5B%22%E7%AE%A1%E7%94%B3%E8%B5%8E%E8%8A%82%E5%A5%8F%22%5D%0A%20%20SAMP%20--%3E%20ACT3%5B%22%E9%87%8D%E5%BB%BA%E6%A8%A1%E4%B8%8E%E9%A2%84%E7%AE%97%22%5D%0A%20%20TRD%20--%3E%20ACT4%5B%22%E5%81%9A%E6%89%A7%E8%A1%8C%E9%A2%84%E7%AE%97%22%5D%0A"})]),fallback:A(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[e("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,"分解之所以重要，是因为各项的修正动作互不可替代。费用选错产品，再好的申赎管理也补不回一百个基点；申赎节奏混乱，换零费率产品也留不住现金拖累。混着报一个总 TE，等于把五种病因开一种药。借出收入尤其要单独看：它解释了为什么两只同指数、同费率的产品 TD 可以差出十个基点以上——差别不在管理，在借贷需求与返还分成。",-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"借出收入可以想象成把空置的房间短租出去补贴房租：篮子里的股票平时「闲着」，借券人付利息、基金拿分成。同样跟踪沪深 300，一只基金借出需求旺盛、分成大头给持有人，另一只几乎借不出去，一年 TD 就能差出十个基点——和管理能力毫无关系。")],-1)),E[6]||(E[6]=a("p",null,"事前与事后的分工同样清楚：事前 TE 用权重差与协方差算，服务于风险预算与复制方式选择；事后 TD 用净值与指数的真实差算，服务于验收与选型。把事前模型当成验收依据，模型里没有的事件成本——下一课要写的指数再平衡——会变成意外的落后；把事后数字直接外推，事件的年度节奏变了，落后也会变。",-1)),(B(),n(o,null,{default:A(()=>[l(r,{id:"mermaid-42",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E5%A4%8D%E5%88%B6%E6%96%B9%E5%BC%8F%E4%B8%8E%E6%9D%83%E9%87%8D%E5%B7%AE%22%5D%20--%3E%20EX%5B%22%E4%BA%8B%E5%89%8D%20TE%EF%BC%9A%E6%9D%83%E9%87%8D%E5%B7%AE%20%C3%97%20%E5%8D%8F%E6%96%B9%E5%B7%AE%22%5D%0A%20%20EX%20--%3E%20U1%5B%22%E7%94%A8%E9%80%94%EF%BC%9A%E9%A3%8E%E9%99%A9%E9%A2%84%E7%AE%97%E4%B8%8E%E5%A4%8D%E5%88%B6%E6%96%B9%E5%BC%8F%E9%80%89%E6%8B%A9%22%5D%0A%20%20R%5B%22%E7%9C%9F%E5%AE%9E%E5%87%80%E5%80%BC%E4%B8%8E%E6%8C%87%E6%95%B0%E7%9A%84%E6%97%A5%E5%B7%AE%22%5D%20--%3E%20PO%5B%22%E4%BA%8B%E5%90%8E%20TD%EF%BC%9A%E9%80%90%E6%97%A5%E7%B4%AF%E5%8A%A0%22%5D%0A%20%20PO%20--%3E%20U2%5B%22%E7%94%A8%E9%80%94%EF%BC%9A%E9%AA%8C%E6%94%B6%E4%B8%8E%E4%BA%A7%E5%93%81%E9%80%89%E5%9E%8B%22%5D%0A%20%20U1%20--%3E%20M1%5B%22%E8%AF%AF%E7%94%A8%EF%BC%9A%E6%8B%BF%E4%BA%8B%E5%89%8D%E6%A8%A1%E5%9E%8B%E5%BD%93%E9%AA%8C%E6%94%B6%E4%B9%A6%22%5D%0A%20%20U2%20--%3E%20M2%5B%22%E8%AF%AF%E7%94%A8%EF%BC%9A%E6%8B%BF%E4%BA%8B%E5%90%8E%E6%95%B0%E5%AD%97%E7%9B%B4%E6%8E%A5%E5%A4%96%E6%8E%A8%22%5D%0A%20%20M1%20--%3E%20C1%5B%22%E4%BA%8B%E4%BB%B6%E6%88%90%E6%9C%AC%E4%B8%8D%E5%9C%A8%E6%A8%A1%E5%9E%8B%E9%87%8C%EF%BC%8C%E5%86%8D%E5%B9%B3%E8%A1%A1%E6%97%A5%E5%8F%98%E6%88%90%E6%84%8F%E5%A4%96%E8%90%BD%E5%90%8E%22%5D%0A%20%20M2%20--%3E%20C2%5B%22%E4%BA%8B%E4%BB%B6%E5%B9%B4%E5%BA%A6%E8%8A%82%E5%A5%8F%E4%B8%80%E5%8F%98%EF%BC%8C%E5%A4%96%E6%8E%A8%E7%9A%84%E8%90%BD%E5%90%8E%E7%AB%8B%E5%8D%B3%E5%A4%B1%E6%95%88%22%5D%0A"})]),fallback:A(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=t('<p><span class="marginnote">常见误区：以为 TE 越小产品越好。TE 只量「贴得稳不稳」，不量「落后多少」——一只每天稳定落后万分之一的产品 TE 近乎为零，十年却累计落后约 2.5%。选被动产品要先看 TD 有没有系统性缺口，再用 TE 排除时贴时离的产品。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>TE 作为合同约束下的优化对象，是<a href="/quant/benchmark-tracking-error">基准与跟踪误差</a>的主题，本课不重推 Roll 的结论。指数增强产品的超额与衰减是另一条线，见<a href="/quant/index-enhancement-decay">指增产品超额衰减</a>。本课的分解表也不声称完备：杠杆与期货化产品有展期项，合成复制有掉期融资项，它们是同一方法多加两列。最后，TD 与 TE 都要用全收益口径的指数来算——<a href="/quant/etf-index-construction">第一课</a>钉过的口径错误，在这里会直接变成虚假的「跟踪差距」。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>TD 有符号、TE 无符号；费率进 TD 不进 TE，验收必须两个量都要。</li><li>每日差可拆成费用、现金拖累、抽样残差、事件成本、借出收入与估值噪声，各项的修正动作互不可替代。</li><li>借出收入是宽基 ETF TD 接近零的机制；同指数同费率的产品可因此差出十个基点级。</li><li>事前 TE 用于预算，事后 TD 用于验收；日频 TE 在跨时区产品上被陈旧价格压低，不可直接比较。</li><li>出处：Roll, <em>Journal of Portfolio Management</em>, 1992；Frino and Gallagher（2001）对指数基金跟踪成本的分解；分项口径据发行人年报与基金说明书整理。</li></ul>',5))])}const _=i(d,[["render",T]]);export{u as __pageData,_ as default};
